            RuntimeState.AutoClicker[parent2] = true

            if flag12 and parent2:FindFirstChild("HumanoidRootPart") then
                local humanoidRootPart = parent2:FindFirstChild("HumanoidRootPart")
                local humanoid = parent2:FindFirstChild("Humanoid")
                local bodyPosition = Instance.new("BodyPosition")
                bodyPosition.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                bodyPosition.D = 100
                bodyPosition.Position = humanoidRootPart.Position
                bodyPosition.Parent = humanoidRootPart

                task.spawn(function()
                    while true do
                        if RuntimeState.AutoClicker[parent2] and humanoidRootPart.Parent and humanoid and humanoid.Parent and humanoid.Health ~= 0 and HelperFunction20() then
                            local LocalValue21, LocalValue22 = UtilityFunctions.Char()

                            if not LocalValue22 then
                                continue
                            elseif not humanoidRootPart:IsDescendantOf(workspace.PlotItems) then
                                task.spawn(UtilityFunctions.Ragdoll, parent2)

                                if UtilityFunctions.GetMagnitude(LocalValue22, humanoidRootPart) <= 32 then
