                    if not (furtherReachBoughtNotifier and furtherReachBoughtNotifier:IsA("RemoteEvent") and limitedTimeToyEvent and limitedTimeToyEvent:IsA("RemoteEvent")) or fartherReach and not fartherReach:IsA("BoolValue") then
                        toggles.FartherReach:SetValue(false)
                        return SendUINotification("Further Reach is unavailable: required game objects are missing or invalid.")
                    end
                    local LocalValue20 = DataTable16
                    local LocalValue21 = DataTable16
                    local LocalValue22 = DataTable16
                    local LocalValue23 = DataTable16
                    DataTable16.Enabled = true
                    LocalValue20.Notifier = furtherReachBoughtNotifier
                    LocalValue21.Event = limitedTimeToyEvent
                    LocalValue22.Events = gamepassEvents
                    LocalValue23.Toys = menuToys
                    local LocalValue24 = DataTable16
