                    furtherReachBoughtNotifier.Parent = workspace
                    limitedTimeToyEvent.Name = "FurtherReachBoughtNotifier"
                    limitedTimeToyEvent.Parent = gamepassEvents
                    local connection = nil

                    local function HelperFunction21(character)
                        if not connection.Connected or IsUnloading then
                            return
                        end
                        local grabbingScript = character and character:WaitForChild("GrabbingScript", 5)
                        if not (connection.Connected and not IsUnloading and character == LocalPlayer.Character and grabbingScript and grabbingScript.Parent == character and grabbingScript:IsA("LocalScript")) then
                            return
                        end

                        if DataTable16.Script then
                            DataTable16.Script:Disconnect()
                        end

                        local function HelperFunction22()
                            if connection.Connected and not IsUnloading and character == LocalPlayer.Character and grabbingScript.Parent == character and grabbingScript.Enabled and limitedTimeToyEvent.Parent then
                                limitedTimeToyEvent:FireServer()
                            end
                        end

                        grabbingScript.Enabled = false
                        grabbingScript.Enabled = true

                        DataTable16.Script = grabbingScript:GetPropertyChangedSignal("Enabled"):Connect(function()
                            if grabbingScript.Enabled then
                                task.delay(1, HelperFunction22)
                            end
                        end)

                        task.delay(1, HelperFunction22)
                    end

                    connection = LocalPlayer.CharacterAdded:Connect(HelperFunction21)
                    DataTable16.Connection = connection
                    task.spawn(HelperFunction21, LocalPlayer.Character)
                else
                    DataTable16.Enabled = false

                    if DataTable16.Connection then
                        DataTable16.Connection:Disconnect()
                    end

                    if DataTable16.Script then
                        DataTable16.Script:Disconnect()
                    end

                    if DataTable16.Line and DataTable16.Line.Parent then
